package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.apache.commons.lang3.builder.EqualsBuilder;
import org.apache.commons.lang3.builder.ToStringBuilder;
import org.apache.commons.lang3.builder.ToStringStyle;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class ArrayUtils_add_TriageGen5Test {

    @Test
    public void testAdd_WithExistingArray() {
        String[] array = {"a", "b"};
        String element = "c";
        String[] expected = {"a", "b", "c"};
        String[] result = ArrayUtils.add(array, element);
        assertArrayEquals(expected, result);
        assertEquals(3, result.length);
    }

    @Test
    public void testAdd_WithIntegerArray() {
        Integer[] array = {1, 2};
        Integer element = 3;
        Integer[] expected = {1, 2, 3};
        Integer[] result = ArrayUtils.add(array, element);
        assertArrayEquals(expected, result);
    }

    @Test
    public void testAdd_WithNullArrayAndNonNullElement() {
        // This covers the branch: else if (element != null) { type = element.getClass(); }
        String element = "onlyElement";
        String[] result = ArrayUtils.add(null, element);

        String[] expected = {"onlyElement"};
        assertArrayEquals(expected, result);
    }

    @Test
    public void testAdd_WithNullArrayAndNullElement() {
        // This covers the branch: else { type = Object.class; }
        // Note: Resulting array will be Object[] containing [null]
        Object[] result = ArrayUtils.add(null, null);

        assertEquals(1, result.length);
        assertNull(result[0]);
    }

    @Test
    public void testAdd_WithEmptyArray() {
        String[] array = {};
        String element = "new";
        String[] expected = {"new"};
        String[] result = ArrayUtils.add(array, element);
        assertArrayEquals(expected, result);
    }

    @Test
    public void testAdd_WithArrayContainingNulls() {
        String[] array = {"a", null, "b"};
        String element = "c";
        String[] expected = {"a", null, "b", "c"};
        String[] result = ArrayUtils.add(array, element);
        assertArrayEquals(expected, result);
    }

    @Test
    public void testAdd_PreservesType() {
        // Ensure that the returned array is of the same component type as the input array
        Integer[] array = {1};
        Integer element = 2;
        Integer[] result = ArrayUtils.add(array, element);

        assertEquals(Integer[].class, result.getClass());
    }
}
